Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using namespace std;

namespace IO {
	template<typename T>
	inline int Read(T &n) {
		T k=0, f=1; char c=getchar();
		while (c<'0' || c>'9') { if (c == '-') f=-1; c=getchar(); }
		while (c>='0' && c<='9') { k=(k<<3)+(k<<1)+(c-'0'); c=getchar(); }
		n = k*f; return 0;
	}
	template<typename T>
	inline void Write(T x) {
		if (x < 0) { putchar('-'); x=-x; }
		if (x > 9) Write(x/10);
		putchar(x%10+'0');
	}
	template<typename T, typename ...Y>
	inline int Read(T &x, Y&... y) { return Read(x) | Read(y...); }
}

#define LL long long
#define FOR(i, a, b) for(LL i=(a); i<=(b); i++)
#define ROF(i, a, b) for(LL i=(a); i>=(b); i--)
const LL Mod1 = 998244353, Mod2 = 1e9+7;
LL ans, n, Cnt1, sum[7];
vector<LL> val[7];
inline void DFS1(LL A, LL B) {
	if (A == 7) return;
	val[A].push_back((Cnt1-B + Mod1) % Mod1);
	sum[A] += (Cnt1-B + Mod1) % Mod1; Cnt1++;
	FOR (i, 0, 9) DFS1(A+1, B*10+i);
}
inline bool check(LL x) {
	const LL Cut = 1e6;
	return x*Cut + 999999 <= n && x*Cut*10 > n;
}
LL Cnt2, Tpow[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};
inline void DFS2(LL A, LL B) {
	if (B > n) return;
	if (check(B)) {
		FOR (i, 0, 6) {
			LL cur = ( (Cnt2 + 1 - (B*Tpow[i])) % Mod1 + Mod1) % Mod1;
			LL pos = lower_bound(val[i].begin(), val[i].end(), Mod1 - cur) - val[i].begin();
			(ans += sum[i] + cur*val[i].size() - Mod1*(val[i].size()-pos)) %= Mod2;
		}
		Cnt2 += Cnt1;
	} else {
		Cnt2++; (ans += ((Cnt2-B)%Mod1 + Mod1) % Mod1) %= Mod2;
		FOR (i, !A, 9) DFS2(A+1, B*10+i);
	}
}
signed main() {
	IO::Read(n); DFS1(0, 0);
	FOR (i, 0, 6) sort(val[i].begin(), val[i].end());
	Cnt2 = -1, DFS2(0, 0); IO::Write(ans);
}
